def verify_bitonic(arr):
    """Check if array is bitonic (increases then decreases)."""
    if len(arr) <= 1:
        return True
    peak = 0
    for i in range(1, len(arr)):
        if arr[i] > arr[peak]:
            peak = i
        elif arr[i] < arr[peak]:
            break
    else:
        # Check if we went down after peak
        for i in range(peak + 1, len(arr)):
            if arr[i] > arr[i - 1]:
                return False
    return True

