    lines = input_data.strip().split('\n')
    n = int(lines[0])

    if n == 1:
        return "1\n"

    adj = [[] for _ in range(n + 1)]
    for i in range(n - 1):
        a, b = map(int, lines[i + 1].split())
        adj[a].append(b)
        adj[b].append(a)

    def dfs(u, p):
        # Returns a dict: for each possible size of component containing u,
        # stores the max product of all *other* completed components in the subtree
        dp = {1: 1}  # base case: component contains just u, product of completed components is 1 (empty product)

        for v in adj[u]:
            if v == p:
                continue
            child_dp = dfs(v, u)

            new_dp = {}

            for sz_u, prod_u in dp.items():
                for sz_v, prod_v in child_dp.items():
                    # Option 1: Cut edge (u,v) → v's subtree is a separate component
                    # size sz_v contributes to product or becomes new completed component
                    # Wait - we need to track what we include in product

                    # Actually: we can either:
                    # 1. Keep edge (u,v): component_size becomes sz_u + sz_v, no new completed component
                    # 2. Cut edge (u,v): v's subtree is completed component of size sz_v, update product

                    new_sz = sz_u + sz_v
                    new_prod = prod_u * prod_v
                    # We need to handle the case where we might update this size with better product
                    if new_sz not in new_dp or new_prod > new_dp[new_sz]:
                        new_dp[new_sz] = new_prod

                    # Option 2: Cut edge (u,v) - v's component is completed with sz_v nodes
                    # Add sz_v to product
                    cut_prod = prod_u * prod_v * sz_v
                    if new_sz not in new_dp or cut_prod > new_dp[new_sz]:
                        new_dp[new_sz] = max(cut_prod, new_dp.get(new_sz, 0))

            dp = new_dp

        return dp

    # The answer is the maximum product for u=1 with no constraint on final component size
    # But wait - the final component also contributes to the product!
    # Actually we need the max over all possible component sizes * that size

    result_dp = dfs(1, -1)
    result = max(sz * prod for sz, prod in result_dp.items())

    return f"{result}\n"

