        # Any sequence with 0 or 1 element is geometric
        if len(seq) <= 1:
            return True

        # All zeros form a geometric progression
        if all(x == 0 for x in seq):
            return True

        # If first element is zero, all must be zero (handled above)
        if seq[0] == 0:
            return False

        # Compute ratio from first two elements as reduced fraction
        num, den = seq[1], seq[0]
        g = gcd(num, den)
        num //= g
        den //= g

        # Ensure denominator is positive
        if den < 0:
            num = -num
            den = -den

        # Verify all consecutive pairs maintain the same ratio
        for i in range(len(seq) - 1):
            a, b = seq[i], seq[i+1]
            if a == 0:
                if b != 0:
                    return False
            else:
                # Check using cross-multiplication to avoid float precision issues
                # b/a == num/den  <=>  b*den == a*num
                if b * den != a * num:
                    return False

        return True

    # Check if already geometric
    if is_geometric(arr):
        return '0\n'

    # Try removing each element
    for i in range(n):
        temp = arr[:i] + arr[i+1:]
        if is_geometric(temp):
