def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = list(map(int, lines[i + 1].split()))
        edges.append({'u': parts[0], 'v': parts[1], 'e': parts[2], 'idx': i})

    # Sort edges by energy for Kruskal's MST
    sorted_edges = sorted(edges, key=lambda x: x['e'])

    # Union-Find with path compression and union by rank
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    # Build MST and track indices
    mst_indices = set()
    for edge in sorted_edges:
        if union(edge['u'], edge['v']):
            mst_indices.add(edge['idx'])

    # Build adjacency list for MST
    adj = [[] for _ in range(n + 1)]
    for edge in sorted_edges:
        if edge['idx'] in mst_indices:
            adj[edge['u']].append((edge['v'], edge['e']))
            adj[edge['v']].append((edge['u'], edge['e']))

    # Preprocess for LCA and max edge queries using binary lifting
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    max_edge = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)
    discovery_order = []

    def dfs(u, d, p, w):
        visited[u] = True
        depth[u] = d
        up[0][u] = p
        max_edge[0][u] = w
        discovery_order.append(u)
        for v, weight in adj[u]:
            if not visited[v]:
                dfs(v, d + 1, u, max(w, weight))
                discovery_order.append(v)

    dfs(1, 0, 1, 0)

    # Build binary lifting table
    for j in range(1, LOG):
        for i in range(1, n + 1):
            up[j][i] = up[j - 1][up[j - 1][i]]
            max_edge[j][i] = max(max_edge[j - 1][i], max_edge[j - 1][up[j - 1][i]])

    # Find LCA
    def find_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        for j in range(LOG - 1, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                u = up[j][u]

        if u == v:
            return u

        for j in range(LOG - 1, -1, -1):
            if up[j][u] != up[j][v]:
                u = up[j][u]
                v = up[j][v]

        return up[0][u]

    # Find max edge weight on path between u and v
    def find_max_on_path(u, v):
        lca = find_lca(u, v)
        res = 0

        def climb(u, lca_node):
            nonlocal res
            curr = u
            while depth[curr] > depth[lca_node]:
                diff = depth[curr] - depth[lca_node]
                for j in range(LOG):
                    if diff & (1 << j):
                        res = max(res, max_edge[j][curr])
                        curr = up[j][curr]

        climb(u, lca)
        climb(v, lca)
        return res

    # Process non-MST edges
    results = []
    for edge in edges:
        if edge['idx'] not in mst_indices:
            max_e = find_max_on_path(edge['u'], edge['v'])
            results.append(str(max_e))

    return '\n'.join(results) + '\n' if results else ''

