    n, m, r, k = map(int, input_str.split())

    def compute_coverage(size, scoop_size):
        """Computes coverage for each position in a 1D array"""
        ans = []
        for i in range(1, size + 1):
            # A position i is covered by scoop top-left positions in:
            # [max(1, i - r + 1), min(i, size - r + 1)]
            low = max(1, i - scoop_size + 1)
            high = min(i, size - scoop_size + 1)
            count = max(0, high - low + 1)
            ans.append(count)
        return ans

    cov_x = compute_coverage(n, r)
    cov_y = compute_coverage(m, r)

    # Sort in descending order to get largest coverages
    cov_x.sort(reverse=True)
    cov_y.sort(reverse=True)

    total_positions = (n - r + 1) * (m - r + 1)

    # Generate top k products efficiently using max-heap
    # Avoid O(n*m) which can be huge; we only need top k
    ans = 0
    visited = set()
    heap = []

    # Start with (0, 0) - the largest product (cov_x[0]*cov_y[0])
    heappush(heap, (-cov_x[0] * cov_y[0], 0, 0))
    visited.add((0, 0))

    count = 0
    while heap and count < k:
        neg_prod, i, j = heappop(heap)
        ans -= neg_prod
        count += 1

        # Try moving to next in x (down-right neighbors)
        if i + 1 < n and (i + 1, j) not in visited:
            heappush(heap, (-cov_x[i + 1] * cov_y[j], i + 1, j))
            visited.add((i + 1, j))

        # Try moving to next in y
        if j + 1 < m and (i, j + 1) not in visited:
            heappush(heap, (-cov_x[i] * cov_y[j + 1], i, j + 1))
            visited.add((i, j + 1))

    expected = ans / total_positions

    return f"{expected:.10f}"

