class Tokenizer:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def peek(self):
        if self.pos >= len(self.s):
            return None
        return self.s[self.pos]

    def advance(self):
        ch = self.s[self.pos]
        self.pos += 1
        return ch

    def match(self, pattern, type_name=None):
        if pattern[0] == '<' and pattern[1] == '=':
            # Rule: <expression>
            if self.peek() in ['+', '-']:
                return None
            ch = self.advance()
            if type_name:
                return self
            return ch
        elif pattern[0] == '<' and pattern[1] == 'n':
            # Parse number
            num = 0
            digits = 0
            start_pos = self.pos
            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                num = num * 10 + int(self.s[self.pos])
                self.pos += 1
                digits += 1
            return (num, digits, start_pos)

    def parse(self):
        """Parse the expression and return value mod MOD."""
        return self.parse_expr()

    def parse_expr(self):
        """<expression> ::= <term> | <expression> '+' <term>"""
        tokens = []
        token = self.parse_term()
        while token[0] == '+':
            tokens.append('+')
            token = self.parse_term()
            tokens.append(token[1])
        tokens.append(None)
        return tokens

    def parse_term(self):
        """<term> ::= <number> | <number> '-' <number> | <number> '(' <expression> ')'"""
        if self.pos >= len(self.s):
            return (0, 0)

        if self.s[self.pos] == '(':
            # number '(' expression ')' - this is nested in repetition context
            return self.parse_repetition()

        if self.s[self.pos] == '-':
            # number '-' number
            return self.parse_range()

        return self.parse_number_term()

    def parse_repetition(self):
        """number '(' expression ')'"""
        result = 0
        cnt = 0
        pos = self.pos

        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            result = result * 10 + int(self.s[self.pos])
            self.pos += 1
        cnt = result

        if self.s[self.pos] == '(':
            self.advance()
            inner_value = self.parse_expr()

            if self.s[self.pos] == ')':
                self.advance()

            return (cnt, inner_value)

        return (0, 0)

    def parse_range(self):
        """number '-' number"""
        if self.pos >= len(self.s) or self.s[self.pos] != '-':
            return self.parse_number_term()

        l = 0
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            l = l * 10 + int(self.s[self.pos])
            self.pos += 1

        if self.pos < len(self.s) and self.s[self.pos] == '-':
