            r = 0
            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                r = r * 10 + int(self.s[self.pos])
                self.pos += 1

        return l, r

    def parse_number_term(self):
        """Just a single number"""
        result = 0
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            result = result * 10 + int(self.s[self.pos])
            self.pos += 1
        return result

