def solve_test(p):
    """Solve for a single test case with lantern powers p."""
    n = len(p)
    directions = [''] * n

    # Process from right to left
    for i in range(n - 1, -1, -1):
        is_covered = False

        # Check if already covered from the left (i-1 going R)
        if i > 0 and directions[i - 1] == 'R':
            if i <= (i - 1) + p[i - 1]:
                is_covered = True

        # Check if already covered from the right (i+1 going L)
        if i < n - 1 and directions[i + 1] == 'L':
            if i >= (i + 1) - p[i + 1]:
                is_covered = True

        if is_covered:
            # Already covered, try to help cover someone to the left
            if directions[i] == '':
                # Default to L to try helping cover i-1 or i-2 etc
                directions[i] = 'L'
            continue

        # i is not covered - need to set a neighbor's direction
        # Try first: use i+1 going left to cover i
        if not is_covered:
            if i + 1 < n and directions[i + 1] == '':
                if i + 1 - p[i + 1] <= i:  # i+1 going L can cover i
                    directions[i + 1] = 'L'

        # If still not covered, try i-1 going right
        if not is_covered:
            if i - 1 >= 0 and directions[i - 1] == '':
                if i <= (i - 1) + p[i - 1]:  # i-1 going R can cover i
                    directions[i - 1] = 'R'

    # Verify all positions are covered
    for i in range(n):
        covered = False
        if i > 0 and directions[i - 1] == 'R' and i <= (i - 1) + p[i - 1]:
            covered = True
        if i < n - 1 and directions[i + 1] == 'L' and i >= (i + 1) - p[i + 1] and not covered:
            covered = True

        # Try with current direction too
        if not covered and directions[i] == 'R':
            if i < n - 1:
                covered = True
        if not covered and directions[i] == 'L':
            if i > 0:
                covered = True

    # Check actually covered by others
    all_covered = True
    for i in range(n):
        covered_by_others = False
        for j in range(n):
            if i == j:
                continue
            # j going R covers i
            if directions[j] == 'R':
                if j < i and i <= j + p[j]:
                    covered_by_others = True
                    break
                if j > i and i >= j + 1 - p[j]:
                    covered_by_others = True
                    break
            # j going L covers i
            if directions[j] == 'L':
                if j < i and i >= j + 1 - p[j]:
                    covered_by_others = True
                    break
                if j > i and i <= j - 1 + p[j]:
                    covered_by_others = True
                    break
        if not covered_by_others:
            all_covered = False
            break

    if all_covered:
        return ''.join(directions)
    else:
        # Need to fix and retry or return NO
        return "NO"


