from itertools import combinations

def solution(input_str):
    n, r = map(int, input_str.split())

    # Find all integer points within distance r from origin
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.append((x, y))

    max_sum = -1
    best_positions = []

    # Check all combinations of n positions
    # Since n is small (≤8) and r is small (≤30), this is feasible
    for combo in combinations(range(len(points)), n):
        positions = [points[i] for i in combo]

        # Calculate sum of squared pairwise distances
        current_sum = 0
        for i in range(n):
            for j in range(i + 1, n):
                dx = positions[i][0] - positions[j][0]
                dy = positions[i][1] - positions[j][1]
                current_sum += dx*dx + dy*dy

        if current_sum > max_sum:
            max_sum = current_sum
            best_positions = positions

    # Generate output
    output = [str(max_sum)]
    for x, y in best_positions:
        output.append(f"{x} {y}")
    return "\n".join(output)

